#include <stdio.h>
#include <string.h>

int is_subdomain(const char* url, const char* domain) {
    const char* protocol_end = strstr(url, "://") + 3;
    const char* domain_end = strchr(protocol_end, '/');
    size_t domain_len = domain_end ? domain_end - protocol_end : strlen(protocol_end);

    return strncmp(protocol_end, domain, domain_len) == 0;
}

int main() {
    printf("Is 'blog.example.com' a subdomain of 'example.com'? %s\n", 
           is_subdomain("https://blog.example.com/posts", "example.com") ? "Yes" : "No");
    printf("Is 'example.com' a subdomain of 'example.com'? %s\n", 
           is_subdomain("https://example.com/service", "example.com") ? "Yes" : "No");
    printf("Is 'another.com' a subdomain of 'example.com'? %s\n", 
